def process(loadBNovel, loadCAlternate) -> pd.DataFrame:
    import pandas as pd
    target = 'HPKPEVLGSSADGALLVSLDGLR'

    def search(df: pd.DataFrame, sheet: str) -> pd.DataFrame:
        # find candidate columns that may contain peptide sequence
        cols = [c for c in df.columns if any(k in str(c).lower() for k in ['peptide', 'sequence', 'pep'])]
        if not cols:
            cols = list(df.columns)
        rows = []
        for col in cols:
            s = df[col].astype(str)
            exact = (s == target).sum()
            contains = s.str.contains(target, na=False).sum()
            # I/L ambiguity (also treat J as I/L occasionally)
            regex = target.replace('I', '[IL]').replace('L', '[IL]')
            il = s.str.contains(regex, na=False, regex=True).sum()
            if exact or contains or il:
                rows.append({'sheet': sheet, 'column': col, 'exact': int(exact), 'contains': int(contains), 'IL_regex': int(il)})
        if rows:
            return pd.DataFrame(rows)
        return pd.DataFrame([{'sheet': sheet, 'column': None, 'exact': 0, 'contains': 0, 'IL_regex': 0}])

    out = pd.concat([
        search(loadBNovel, 'B-Novel Splice Junctions'),
        search(loadCAlternate, 'C-Alternate Splice Junctions')
    ], ignore_index=True)
    return out
